    "src/interfaces/upgrades/IInfraredBERAV2.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IInfraredBERAV2 is IERC20, IAccessControl {
    /// @notice Emitted when InfraredBERA is minted
    /// @param receiver The address receiving the minted shares
    /// @param amount The amount of BERA deposited
    /// @param shares The amount of shares minted
    event Mint(address indexed receiver, uint256 amount, uint256 shares);

    /// @notice Emitted when InfraredBERA is burned
    /// @param receiver The address receiving the withdrawn BERA
    /// @param nonce The withdrawal nonce
    /// @param amount The amount of BERA to withdraw
    /// @param shares The amount of shares burned
    /// @param fee The fee paid for withdrawal
    event Burn(
        address indexed receiver,
        uint256 nonce,
        uint256 amount,
        uint256 shares,
        uint256 fee
    );

    /// @notice Emitted when accumulated rewards are swept
    /// @param amount The amount of BERA swept
    event Sweep(uint256 amount);

    /// @notice Emitted when validator stake is registered
    /// @param pubkey The validator's public key
    /// @param delta The change in stake amount
    /// @param stake The new total stake amount
    event Register(bytes pubkey, int256 delta, uint256 stake);

    /// @notice Emitted when validator stake is registered via proofs
    /// @param pubkey The validator's public key
    /// @param effectiveBalance CL effective balance
    /// @param stake The previous internal balance
    event RegisterViaProof(
        bytes pubkey, uint256 effectiveBalance, uint256 stake
    );

    /// @notice Emitted when fee shareholders rate is updated
    /// @param from Previous fee rate
    /// @param to New fee rate
    event SetFeeShareholders(uint16 from, uint16 to);

    /// @notice Emitted when deposit signature is updated
    /// @param pubkey The validator's public key
    /// @param from Previous signature
    /// @param to New signature
    event SetDepositSignature(bytes pubkey, bytes from, bytes to);

    /// @notice Emitted when withdrawal flag is updated
    /// @param flag New withdrawal flag value
    event WithdrawalFlagSet(bool flag);

    /// @notice Emitted when exit fees are claimed by governance
    /// @param amount The amount of iBERA fees collected
    /// @param to Address iBERA sent sent to
    event ExitFeesCollected(uint256 amount, address to);

    /// @notice Emitted when buen fee updated by governance
    /// @param fee The amount of iBERA fee to charge on burns
    event BurnFeeUpdated(uint256 fee);

    /// @notice Emitted when rate provider updated by governance
    /// @param provider New rate provider address
    event RateProviderUpdated(address provider);

    /// @notice Emitted when proof time buffer updated by governance
    /// @param newBuffer new timespan in seconds to allow staleness of proof data relative to current head
    event ProofTimestampBufferUpdated(uint256 newBuffer);

    /// @notice The `Infrared.sol` smart contract
    function infrared() external view returns (address);

    /// @notice The `InfraredBERADepositor.sol` smart contract
    function depositor() external view returns (address);

    /// @notice The `InfraredBERAWithdrawor.sol` smart contract
    function withdrawor() external view returns (address);

    /// @notice The `InfraredBERAFeeReceivor.sol` smart contract
    function receivor() external view returns (address);

    /// @notice The total amount of `BERA` deposited by the system
    function deposits() external view returns (uint256);

    /// @notice Returns the amount of `BERA` staked in validator with given pubkey
    function stakes(bytes calldata pubkey) external view returns (uint256);

    /// @notice Returns whether initial deposit has been staked to validator with given pubkey
    function staked(bytes calldata pubkey) external view returns (bool);

    /// @notice Returns whether a validator pubkey has exited
    function hasExited(bytes calldata pubkey) external view returns (bool);

    /// @notice Returns the deposit signature to use for given pubkey
    function signatures(bytes calldata pubkey)
        external
        view
        returns (bytes memory);

    /// @notice The fee divisor for protocol + operator + voter fees. 1/N, where N is the divisor. example 100 = 1/100 = 1%
    function feeDivisorShareholders() external view returns (uint16);

    /// @notice Pending deposits yet to be forwarded to CL
    function pending() external view returns (uint256);

    /// @notice Confirmed deposits sent to CL, total - future deposits
    function confirmed() external view returns (uint256);

    /// @notice Time, in seconds, allowed for staleness of proof data relative to current head
    function proofTimestampBuffer() external view returns (uint256);

    /// @notice Checks if account has the keeper role
    /// @param account The address to check
    /// @return True if the account has the keeper role
    function keeper(address account) external view returns (bool);

    /// @notice Checks if account has the governance role
    /// @param account The address to check
    /// @return True if the account has the governance role
    function governor(address account) external view returns (bool);

    /// @notice Checks if a given pubkey is a validator in the `Infrared` contract
    /// @param pubkey The pubkey to check
    /// @return True if the pubkey is a validator
    function validator(bytes calldata pubkey) external view returns (bool);

    /// @notice Previews the amount of InfraredBERA shares that would be minted for a given BERA amount
    /// @param beraAmount The amount of BERA to simulate depositing
    /// @return shares The amount of InfraredBERA shares that would be minted, returns 0 if the operation would fail
    function previewMint(uint256 beraAmount)
        external
        view
        returns (uint256 shares);

    /// @notice Previews the amount of BERA that would be received for burning InfraredBERA shares
    /// @param shareAmount The amount of InfraredBERA shares to simulate burning
    /// @return beraAmount The amount of BERA that would be received, returns 0 if the operation would fail
    /// @return fee The fee that would be charged for the burn operation in iBERA
    function previewBurn(uint256 shareAmount)
        external
        view
        returns (uint256 beraAmount, uint256 fee);

    /// @notice Internal function to update top level accounting and compound rewards
    function compound() external;

    /// @notice Compounds accumulated EL yield in fee receivor into deposits
    /// @dev Called internally at bof whenever InfraredBERA minted or burned
    /// @dev Only sweeps if amount transferred from fee receivor would exceed min deposit thresholds
    function sweep() external payable;

    /// @notice Collects yield from fee receivor and mints ibera shares to Infrared
    /// @dev Called in `RewardsLib::harvestOperatorRewards()` in `Infrared.sol`
    /// @dev Only Infrared can call this function
    /// @return sharesMinted The amount of ibera shares
    function collect() external returns (uint256 sharesMinted);

    /// @notice Mints `ibera` to the `receiver` in exchange for `bera`
    /// @dev takes in msg.value as amount to mint `ibera` with
    /// @param receiver The address to mint `ibera` to
    /// @return shares The amount of `ibera` minted
    function mint(address receiver) external payable returns (uint256 shares);

    /// @notice Burns `ibera` from the `msg.sender` and sets a receiver to get the `BERA` in exchange for `iBERA`
    /// @param receiver The address to send the `BERA` to
    /// @param shares The amount of `ibera` to burn
    /// @return nonce The nonce of the withdrawal. Queue based system for withdrawals
    /// @return amount The amount of `BERA` withdrawn for the exchange of `iBERA`
    function burn(address receiver, uint256 shares)
        external
        returns (uint256 nonce, uint256 amount);

    /// @notice Updates the accounted for stake of a validator pubkey
    /// @param pubkey The pubkey of the validator
    /// @param delta The change in stake
    function register(bytes calldata pubkey, int256 delta) external;

    /// @notice Sets the fee shareholders taken on yield from EL coinbase priority fees + MEV
    /// @param to The new fee shareholders represented as an integer denominator (1/x)%
    function setFeeDivisorShareholders(uint16 to) external;

    /// @notice Sets the deposit signature for a given pubkey. Ensure that the pubkey has signed the correct deposit amount of `INITIAL_DEPOSIT`
    /// @param pubkey The pubkey to set the deposit signature for
    /// @param signature The signature to set for the pubkey
    function setDepositSignature(
        bytes calldata pubkey,
        bytes calldata signature
    ) external;

    /// @notice Whether withdrawals are currently enabled
    function withdrawalsEnabled() external view returns (bool);
}
"
    },
    "src/interfaces/upgrades/IInfraredBERAWithdrawor.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IInfraredBERAWithdrawor {
    /// @notice Emitted when a withdrawal is queued
    /// @param receiver The address that will receive the withdrawn BERA
    /// @param nonce The unique identifier for this withdrawal request
    /// @param amount The amount of BERA to be withdrawn
    event Queue(address indexed receiver, uint256 nonce, uint256 amount);

    /// @notice Emitted when a withdrawal is executed
    /// @param pubkey The validator's public key
    /// @param amount The amount of BERA withdrawn
    event Execute(bytes pubkey, uint256 amount);

    /// @notice Emitted when a queue is processed
    /// @param receiver The address receiving the withdrawn BERA
    /// @param nonce The nonce of the processed withdrawal
    /// @param amount The amount of BERA processed
    event Process(address indexed receiver, uint256 nonce, uint256 amount);

    /// @notice Emitted when a withdrawal request range is processed
    /// @param startRequestId First request processed
    /// @param finishRequestId Last request processed
    event ProcessRange(uint256 startRequestId, uint256 finishRequestId);

    /// @notice Emitted when a claim is processed
    /// @param receiver The address receiving the withdrawn BERA
    /// @param nonce The nonce of the processed withdrawal
    /// @param amount The amount of BERA processed
    event Claimed(address indexed receiver, uint256 nonce, uint256 amount);

    /// @notice Emitted when funds are swept from a force-exited validator
    /// @param receiver The address receiving the swept BERA
    /// @param amount The amount of BERA swept
    event Sweep(address indexed receiver, uint256 amount);

    /// @notice Emitted when min activation balance is updated by governance
    /// @param newMinActivationBalance New value for min activation balance to maintain activity
    event MinActivationBalanceUpdated(uint256 newMinActivationBalance);

    /// @notice The address of the InfraredBERA contract
    function InfraredBERA() external view returns (address);

    /// @notice Sweeps forced withdrawals to InfraredBERA to re-stake principal
    /// @param pubkey The validator's public key to sweep funds from
    /// @dev Only callable when withdrawals are disabled and by keeper
    // function sweep(bytes calldata pubkey) external;

    /// @notice State of a withdrawal request ticket.
    /// @dev QUEUED: Ticket is queued and awaiting processing. PROCESSED: Ticket is finalized and claimable (or rebalanced for depositor). CLAIMED: Ticket has been claimed by the receiver.
    enum RequestState {
        QUEUED,
        PROCESSED,
        CLAIMED
    }

    /// @notice The request struct for withdrawal requests.
    /// @param state records whether queued, processed or claimed
    /// @param timestamp The block.timestamp at which the withdraw request was issued.
    /// @param receiver The address of the receiver of the withdrawn BERA funds.
    /// @param amount The amount of BERA to be claimed by receiver.
    /// @param accumulatedAmount Running total amount withdrawn inclusive of this ticket.
    struct WithdrawalRequest {
        RequestState state;
        uint88 timestamp;
        address receiver;
        uint128 amount;
        uint128 accumulatedAmount;
    }

    /// @notice Mapping of request IDs to withdrawal request tickets.
    /// @dev Key is the `requestId` (starting at 1), and value is the `WithdrawalRequest` struct.
    function requests(uint256 nonce)
        external
        view
        returns (
            RequestState state,
            uint88 timestamp,
            address receiver,
            uint128 amount,
            uint128 accumulatedAmount
        );

    /// @notice Struct to track pending withdrawals with expiry
    struct PendingWithdrawal {
        uint160 amount;
        uint96 expiryBlock;
        bytes32 pubkeyHash;
    }

    /// @notice Sums all current pending withdrawals as helper for keeper to calculate how much needs to be executed next
    /// @param pubkeyHash keccak256 of public key for validator to get pending withdrawals for
    /// @return total Sum amount in bera, pending on CL to return to contract
    /// @dev Iterates through pending withdrawals, counting only those that have not expired (fulfilled)
    function getTotalPendingWithdrawals(bytes32 pubkeyHash)
        external
        view
        returns (uint256 total);

    /// @notice Amount of BERA internally set aside to process withdraw compile requests from funds received on successful requests
    function reserves() external view returns (uint256);

    /// @notice Retrieves the current fee required by the withdrawal precompile.
    /// @return fee The fee (in wei) required for a withdrawal request.
    /// @dev Performs a static call to the precompile. Reverts if the call fails or the response is invalid (not 32 bytes).
    function getFee() external view returns (uint256 fee);

    /// @notice Returns the total amount of BERA queued for withdrawal across all unprocessed tickets.
    /// @return queuedAmount The total amount of BERA (in wei) in `QUEUED` tickets from `requestsFinalisedUntil + 1` to `requestLength`.
    /// @dev Calculates the difference between the cumulative amount at `requestLength` and `requestsFinalisedUntil`.
    /// @dev Returns 0 if `requestLength == requestsFinalisedUntil` (no unprocessed tickets) or `requestLength == 0` (no tickets queued).
    /// @dev Assumes tickets from `requestsFinalisedUntil + 1` to `requestLength` are in `QUEUED` state, as enforced by `process`.
    function getQueuedAmount() external view returns (uint256 queuedAmount);

    /// @notice Calculates the highest request ID that can be finalized by `process` given the current reserves.
    /// @return newRequestsFinalisedUntil The highest `requestId` (inclusive) that can be processed without exceeding available reserves, or 0 if no tickets can be processed.
    /// @dev Iterates through unprocessed tickets (`requestsFinalisedUntil + 1` to `requestLength`) to find the maximum number of requests whose cumulative amount does not exceed `reserves()`.
    /// @dev Returns `requestsFinalisedUntil` if no additional tickets can be processed due to insufficient reserves.
    function getRequestsToProcess()
        external
        view
        returns (uint256 newRequestsFinalisedUntil);

    /// @notice Queues a withdraw request from InfraredBERA
    /// @param receiver The address to receive withdrawn funds
    /// @param amount The amount of funds to withdraw
    /// @return nonce The unique identifier for this withdrawal request
    /// @dev Requires msg.value to cover minimum withdrawal fee
    function queue(address receiver, uint256 amount)
        external
        returns (uint256 nonce);

    /// @notice Executes a withdraw request to withdraw precompile
    /// @param pubkey The validator's public key to withdraw from
    /// @param amount The amount of BERA to withdraw
    /// @dev Payable to cover any additional fees required by precompile
    /// @dev Only callable by keeper
    // function execute(bytes calldata pubkey, uint256 amount) external payable;

    /// @notice Finalizes a range of withdrawal requests, marking them as claimable or rebalancing to the depositor.
    /// @param newRequestsFinalisedUntil The highest `requestId` to finalize (inclusive).
    /// @dev Reverts if:
    /// - `newRequestsFinalisedUntil` exceeds `requestLength`.
    /// - `newRequestsFinalisedUntil` is less than or equal to `requestsFinalisedUntil`.
    /// - Available reserves are insufficient for the total amount to finalize.
    /// @dev Accumulates amounts for depositor rebalancing into a single call to `InfraredBERADepositor.queue`.
    /// @dev Updates `totalClaimable` for non-depositor tickets.
    function process(uint256 newRequestsFinalisedUntil) external;

    /// @notice Claims a finalized withdrawal request for a user.
    /// @param requestId The ID of the withdrawal request to claim.
    /// @dev Reverts if:
    /// - `requestId` exceeds `requestsFinalisedUntil` (not finalized).
    /// - Ticket is not in `PROCESSED` state or belongs to the depositor.
    /// @dev Transitions the ticket to `CLAIMED` and transfers the amount to the receiver.
    function claim(uint256 requestId) external;

    /// @notice Claims multiple finalized withdrawal requests in a single transaction.
    /// @param requestIds An array of request IDs to claim.
    /// @param receiver recipient address of all requestId's
    /// @dev Reverts if:
    /// - Any `requestId` exceeds `requestsFinalisedUntil` (not finalized).
    /// - Any ticket is not in `PROCESSED` state or belongs to the depositor.
    /// @dev Transitions each ticket to `CLAIMED` and transfers the total amount to the caller.
    /// @dev Emits a `Claimed` event for each claimed ticket.
    function claimBatch(uint256[] calldata requestIds, address receiver)
        external;
}
"
